KEY = "qwen7b"
GOLD_DIR = Path("/data/agastyas/nla_mimic/out_corpus_qwen7b")
OUT_DIR = Path("/data/agastyas/nla_mimic/claim_ablation_atoms")
OUT_DIR.mkdir(parents=True, exist_ok=True)
R, ALPHA, NULL_PCT, SPEC_MARGIN = 10, 1.0, 95.0, 1.5

def main():
    cfg = MODELS[KEY]
    gold = np.load(GOLD_DIR / "gold.npy")
    print(f"[CP4] {cfg['label']} L{cfg['layer']}  {len(DATA)} activations", flush=True)
    print(f"loading AV {cfg['av']} ...", flush=True)
    av_dir = snapshot_download(cfg["av"])
    tok = AutoTokenizer.from_pretrained(av_dir, trust_remote_code=True)
    sc = read_sidecar(av_dir)
    _, model = load_av(cfg)
    inj = ca.register_injector(model, sc, cfg["family"], tok)
    print(f"loading AR {cfg['ar']} ...", flush=True)
    ar_dir = snapshot_download(cfg["ar"])
    critic = NLACritic(ar_dir, device_map="auto")
    print(f"injection_scale={sc['injection_scale']}  mse_scale={critic.mse_scale}", flush=True)

    out_recs, deltas_store = [], {}
    for d in DATA:
        IDX = d["idx"]
        rec, vec = ca.audit_activation_atoms(
            model, tok, sc, cfg["family"], critic, inj, gold[IDX],
            z_assistant=d["explanation"], z_inner=d["z_inner"], atoms=d["atoms"],
            R=R, alpha=ALPHA, null_pct=NULL_PCT, spec_margin=SPEC_MARGIN, seed=IDX,
            idx=IDX, doc_id=d["doc_id"], position=d["position"],
            n_tokens=d["n_tokens"], read_token=d["read_token"])
        out_recs.append(rec)
        if vec is not None:
            deltas_store[str(IDX)] = vec["deltas"].astype(np.float32)
        bt = rec.get("by_type", {})
        bt_s = "  ".join(f"{t}:{v['grounded']}g/{v['entangled']}e/{v['confabulated']}c" for t, v in sorted(bt.items()))
        print(f"  idx {IDX:3d}  n_content={rec['n_content']:2d}  located={rec['located_count']:2d}  "
              f"grounded={rec['grounded_count']} entangled={rec['entangled_count']} confab={rec['confab_count']}  | {bt_s}", flush=True)

    (OUT_DIR / "cp4_records.json").write_text(json.dumps(out_recs, ensure_ascii=False, indent=2))
    np.savez_compressed(OUT_DIR / "cp4_deltas.npz", **deltas_store)
    print(f"[CP4] wrote {OUT_DIR/'cp4_records.json'} ({len(out_recs)} recs) and cp4_deltas.npz", flush=True)

if __name__ == "__main__":
    main()
